package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

// DATA DIVISION derived types
type AmtRec struct { // 01 AMT-REC, 11 bytes
	ArAcct string          // PIC X(4) @0 len=4
	ArAmt  decimal.Decimal // PIC 9(5)V99 @4 len=7
}

// Standalone working-storage items
var WsEofFlag string = "N"                            // PIC X len=1 = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(7)V99
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99
var WsOverflows int64 = 0                               // PIC 99
var WsCount int64 = 0                                   // PIC 99
var WsHalf decimal.Decimal = decimal.NewFromInt(0)     // PIC 9(5)V9
var WsAmtEd string                                      // PIC ZZ,ZZ9.99 len=9
var WsWrapEd string                                     // PIC ZZ,ZZ9.99 len=9
var WsSafeEd string                                     // PIC ZZ,ZZ9.99 len=9
var WsHalfEd string                                     // PIC ZZ,ZZ9.9 len=8

// file handling
var amtFile *os.File
var scanner *bufio.Scanner
var curRec AmtRec

// helpers
func pow10(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func maxDecimal(intDigits, scale int) decimal.Decimal {
	base := pow10(intDigits + scale)
	return decimal.New(base-1, -int32(scale))
}

func isOverflow(val decimal.Decimal, intDigits, scale int) bool {
	if val.IsNegative() {
		return true
	}
	mx := maxDecimal(intDigits, scale)
	return val.GreaterThan(mx)
}

func storeDrop(val decimal.Decimal, intDigits, scale int) decimal.Decimal {
	trunc := val.Truncate(int32(scale))
	shifted := trunc.Shift(int32(scale)).Truncate(0)
	scaledInt := shifted.IntPart()
	base := pow10(intDigits + scale)
	var mod int64
	if scaledInt >= 0 {
		mod = scaledInt % base
	} else {
		mod = -((-scaledInt) % base)
	}
	return decimal.New(mod, -int32(scale))
}

func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracSlots++
		}
	}
	vAbs := val.Abs()
	vTrunc := vAbs.Truncate(int32(fracSlots))
	shifted := vTrunc.Shift(int32(fracSlots)).Truncate(0)
	scaledInt := shifted.IntPart()
	powFrac := pow10(fracSlots)
	var intPart, fracPart int64
	if fracSlots > 0 {
		intPart = scaledInt / powFrac
		fracPart = scaledInt % powFrac
		if fracPart < 0 {
			fracPart = -fracPart
		}
	} else {
		intPart = scaledInt
		fracPart = 0
	}
	powInt := pow10(intSlots)
	intPartMod := intPart % powInt
	if intPartMod < 0 {
		intPartMod = -intPartMod
	}
	intStr := fmt.Sprintf("%0*d", intSlots, intPartMod)
	picRunes := []rune(intPic)
	resRunes := make([]rune, len(picRunes))
	digitIdx := 0
	for i, ch := range picRunes {
		if ch == 'Z' || ch == '9' {
			resRunes[i] = rune(intStr[digitIdx])
			digitIdx++
		} else {
			resRunes[i] = ch
		}
	}
	seenNonZero := false
	for i, ch := range picRunes {
		if ch == 'Z' {
			if resRunes[i] == '0' && !seenNonZero {
				resRunes[i] = ' '
			} else {
				if resRunes[i] != '0' {
					seenNonZero = true
				}
			}
		} else if ch == '9' {
			if resRunes[i] != '0' {
				seenNonZero = true
			}
		}
	}
	for i, ch := range picRunes {
		if ch == ',' {
			hasLeft := false
			for j := 0; j < i; j++ {
				pj := picRunes[j]
				if pj == 'Z' || pj == '9' {
					if resRunes[j] != ' ' {
						hasLeft = true
						break
					}
				}
			}
			if !hasLeft {
				resRunes[i] = ' '
			}
		}
	}
	intFormatted := string(resRunes)
	if dotIdx >= 0 {
		fracStr := fmt.Sprintf("%0*d", fracSlots, fracPart)
		return intFormatted + "." + fracStr
	}
	return intFormatted
}

func InputDone() bool {
	return WsEofFlag == "Y"
}

func OpenAmtFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		WsEofFlag = "Y"
		amtFile = nil
		scanner = nil
		return
	}
	amtFile = f
	scanner = bufio.NewScanner(f)
	// default buffer is enough for 11 bytes
}

func CloseAmtFile() {
	if amtFile != nil {
		amtFile.Close()
	}
}

// paragraphs

func MainPara() {
	OpenAmtFile()
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	CloseAmtFile()
	SummaryPara()
}

func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) > 11 {
			line = line[:11]
		} else if len(line) < 11 {
			line = line + strings.Repeat(" ", 11-len(line))
		}
		curRec.ArAcct = line[0:4]
		amtStr := line[4:11]
		cleaned := strings.Map(func(r rune) rune {
			if r == ' ' {
				return '0'
			}
			return r
		}, amtStr)
		v, err := strconv.ParseInt(cleaned, 10, 64)
		if err != nil {
			v = 0
		}
		curRec.ArAmt = decimal.New(v, -2)
		WsEofFlag = "N"
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	candBig := WsBigTotal.Add(curRec.ArAmt)
	WsBigTotal = storeDrop(candBig, 7, 2)

	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = storeDrop(WsBigTotal, 5, 2)

	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
	candSafe := WsSafeTotal.Add(curRec.ArAmt)
	if isOverflow(candSafe, 5, 2) {
		OverflowPara()
	} else {
		WsSafeTotal = candSafe
	}

	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 100

	// COMPUTE WS-HALF = AR-AMT / 2  (truncated)
	halfExact := curRec.ArAmt.Div(decimal.NewFromInt(2))
	WsHalf = storeDrop(halfExact, 5, 1)

	// MOVEs to edited
	WsAmtEd = formatEdited(curRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")

	// DISPLAY
	fmt.Printf("%s %s %s %s %s\n", curRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)

	// PERFORM READ-PARA
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("RECORDS: %02d\n", WsCount)
	fmt.Printf("OVERFLOWS: %02d\n", WsOverflows)
}

func OverflowPara() {
	WsOverflows = (WsOverflows + 1) % 100
}

func main() {
	MainPara()
}
